STAKE_KEYS = {"stake_id", "property", "target_set", "question", "rationale", "success_condition", "surrender_condition"}

def valid_stake(value: Any) -> bool:
    return bool(isinstance(value, dict) and set(value) == STAKE_KEYS and isinstance(value.get("stake_id"), str) and re.fullmatch(r"[a-z][a-z0-9-]{2,63}", value["stake_id"]) and value.get("target_set") in {"latent-unblocked", "observed-unblocked"} and all(isinstance(value.get(key), str) and value[key].strip() for key in STAKE_KEYS - {"stake_id"}))

def valid_assimilation(value: Any) -> bool:
    if not isinstance(value, dict) or set(value) != {"action", "prior_disposition", "next_stake", "contact_contract", "rationale"}: return False
    stake, contract = value.get("next_stake"), value.get("contact_contract")
    return bool(value.get("action") == "retire-and-revise" and value.get("prior_disposition") == "incoherent-retired" and valid_stake(stake) and previous.valid_contract(contract) and contract.get("action") == "revise" and stake["target_set"] == contract["target_set"] and isinstance(value.get("rationale"), str) and value["rationale"].strip())

def aligned_assimilation(value):
    return bool(valid_assimilation(value) and value["next_stake"]["target_set"] == "latent-unblocked" and value["contact_contract"]["prediction_relation"] == "equals-target")

